const BASE_TYPE_COUNT = 3;

const hasSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countDistinctMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

export const scoreArmy = (army: Card[]): number => {
  if (!hasSphinx(army)) return 0;
  return countDistinctMonsterTypes(army) > BASE_TYPE_COUNT ? 3 : 2;
};
